// lib/pg.js — PostgreSQL (e.g. Supabase) backend for db.js.
//
// The application's SQL is written for SQLite; translate() rewrites the few
// SQLite-only constructs it uses so the same statements run on PostgreSQL:
//   ? placeholders → $1..$n          strftime(…'now') → UTC ISO-8601 text
//   IS NOT ?       → IS DISTINCT FROM  LIKE → ILIKE (SQLite LIKE is case-insensitive)
//   INSERT into a table with an id column → … RETURNING id (for lastID)
//
// Tables live in their own schema (not `public`), so Supabase's auto-generated
// Data API (PostgREST + the public anon key) cannot reach them.

const fs = require('fs');
const path = require('path');
const { Pool, types } = require('pg');

const NOW_SQLITE = "strftime('%Y-%m-%dT%H:%M:%fZ','now')";
const NOW = `to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')`;
const ID_TABLES = new Set(['users', 'user_credentials', 'identity_verifications', 'support_tickets', 'detections',
    'devices', 'sessions', 'password_resets', 'email_verifications']);

// COUNT/SUM return int8 and AVG numeric, which node-postgres yields as strings; SQLite yields numbers.
const PARSERS = { 20: Number, 1700: Number };
const getTypeParser = (oid, format) => PARSERS[oid] || types.getTypeParser(oid, format);

let SCHEMA = 'fraudshield'; // set from config.dbSchema (validated identifier) by createPool

function createPool(config) {
    SCHEMA = config.dbSchema;
    const u = new URL(config.dbUrl);
    const local = ['localhost', '127.0.0.1', '::1'].includes(u.hostname);
    // Verified TLS. Supabase signs its database certificates with its own root CA (bundled);
    // DATABASE_CA_FILE points at another provider's CA.
    const caFile = config.dbCaFile || path.join(__dirname, '..', 'certs', 'supabase-ca.crt');
    const pool = new Pool({
        host: u.hostname,
        port: Number(u.port) || 5432,
        user: decodeURIComponent(u.username),
        password: decodeURIComponent(u.password),
        database: decodeURIComponent(u.pathname.slice(1)) || 'postgres',
        // eslint-disable-next-line security/detect-non-literal-fs-filename -- operator-supplied config path
        ssl: local ? false : { ca: fs.readFileSync(caFile, 'utf8'), rejectUnauthorized: true },
        max: config.dbPoolSize,
        idleTimeoutMillis: 30000,
        connectionTimeoutMillis: 10000,
        types: { getTypeParser },
        options: `-c search_path=${SCHEMA}`,
    });
    pool.on('error', () => { /* idle connection dropped by the server; the pool replaces it */ });
    return pool;
}

/** Replace ? with $n outside quoted literals (standard SQL quoting: no backslash escapes). */
function numberPlaceholders(sql) {
    let out = '';
    let n = 0;
    let quote = null;
    for (const ch of sql) {
        if (quote) { if (ch === quote) quote = null; out += ch; continue; }
        if (ch === "'" || ch === '"') { quote = ch; out += ch; continue; }
        out += ch === '?' ? `$${++n}` : ch;
    }
    return out;
}

const cache = new Map();
function translate(sql) {
    let hit = cache.get(sql);
    if (hit) return hit;
    let text = numberPlaceholders(sql)
        .split(NOW_SQLITE).join(NOW)
        .replace(/\bIS NOT (\$\d+)/g, 'IS DISTINCT FROM $1')
        .replace(/\bLIKE\b/g, 'ILIKE');
    const table = /^\s*INSERT\s+INTO\s+(\w+)/i.exec(text)?.[1]?.toLowerCase();
    const returnsId = ID_TABLES.has(table) && !/\bRETURNING\b/i.test(text);
    if (returnsId) text += ' RETURNING id';
    hit = { text, returnsId };
    if (cache.size < 1000) cache.set(sql, hit);
    return hit;
}

async function prepareSchema(pool) {
    await pool.query(`CREATE SCHEMA IF NOT EXISTS ${SCHEMA}`);
    // Supabase API roles must never reach application data, even if the schema is exposed later.
    await pool.query(`REVOKE ALL ON SCHEMA ${SCHEMA} FROM PUBLIC`);
    for (const role of ['anon', 'authenticated']) {
        const exists = await pool.query('SELECT 1 FROM pg_roles WHERE rolname = $1', [role]);
        if (exists.rowCount) await pool.query(`REVOKE ALL ON SCHEMA ${SCHEMA} FROM ${role}`);
    }
}

const ID = 'id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY';
const TS = `TEXT NOT NULL DEFAULT ${NOW}`;

// Same steps as db.js MIGRATIONS, in PostgreSQL DDL. Append-only; keep both lists in step.
const MIGRATIONS = [
    async run => {
        await run(`CREATE TABLE IF NOT EXISTS users (
            ${ID},
            full_name VARCHAR(255) NOT NULL,
            email VARCHAR(255) NOT NULL UNIQUE,
            phone_number VARCHAR(20),
            created_at ${TS},
            updated_at ${TS},
            avatar_url VARCHAR(255),
            email_high_risk_enabled INTEGER NOT NULL DEFAULT 1,
            email_weekly_summary_enabled INTEGER NOT NULL DEFAULT 1,
            total_scans INTEGER NOT NULL DEFAULT 0,
            threats_neutralized INTEGER NOT NULL DEFAULT 0,
            community_reports INTEGER NOT NULL DEFAULT 0
        )`);
        await run(`CREATE TABLE IF NOT EXISTS user_credentials (
            ${ID},
            user_id INTEGER NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE,
            password_hash VARCHAR(255) NOT NULL,
            created_at ${TS},
            updated_at ${TS}
        )`);
        await run(`CREATE TABLE IF NOT EXISTS identity_verifications (
            ${ID},
            user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
            document_type TEXT NOT NULL CHECK(document_type IN ('Aadhaar', 'PAN', 'DL', 'Passport')),
            document_number_hash VARCHAR(255) NOT NULL,
            full_name_on_doc VARCHAR(255) NOT NULL,
            dob_on_doc TEXT NOT NULL,
            verification_status TEXT NOT NULL DEFAULT 'Pending' CHECK(verification_status IN ('Pending', 'Approved', 'Rejected')),
            created_at ${TS}
        )`);
        await run(`CREATE TABLE IF NOT EXISTS support_tickets (
            ${ID},
            user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
            name VARCHAR(255) NOT NULL,
            email VARCHAR(255) NOT NULL,
            phone_number VARCHAR(20),
            issue_description TEXT NOT NULL,
            ticket_status TEXT NOT NULL DEFAULT 'Open' CHECK(ticket_status IN ('Open', 'In Progress', 'Closed')),
            created_at ${TS}
        )`);
        await run(`CREATE TABLE IF NOT EXISTS detections (
            ${ID},
            user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
            source TEXT NOT NULL CHECK(source IN ('manual', 'screenshot', 'gmail', 'sms')),
            kind TEXT NOT NULL CHECK(kind IN ('url', 'message')),
            sender TEXT,
            subject TEXT,
            target TEXT NOT NULL,
            risk INTEGER NOT NULL,
            verdict TEXT NOT NULL CHECK(verdict IN ('legit', 'suspicious', 'malicious')),
            confidence INTEGER,
            summary TEXT,
            report TEXT NOT NULL,
            status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open', 'acknowledged', 'resolved', 'false_positive')),
            created_at ${TS}
        )`);
        await run('CREATE INDEX IF NOT EXISTS idx_detections_user_time ON detections(user_id, created_at DESC)');
        await run(`CREATE TABLE IF NOT EXISTS gmail_accounts (
            user_id INTEGER PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
            email TEXT NOT NULL,
            secret TEXT NOT NULL,
            enabled INTEGER NOT NULL DEFAULT 1,
            status TEXT NOT NULL DEFAULT 'connecting',
            last_error TEXT,
            last_uid BIGINT,
            uid_validity TEXT,
            messages_scanned INTEGER NOT NULL DEFAULT 0,
            last_event_at TEXT,
            created_at ${TS}
        )`);
        await run(`CREATE TABLE IF NOT EXISTS devices (
            ${ID},
            user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
            name TEXT NOT NULL,
            platform TEXT NOT NULL DEFAULT 'android',
            token_hash TEXT NOT NULL UNIQUE,
            messages_received INTEGER NOT NULL DEFAULT 0,
            last_seen_at TEXT,
            created_at ${TS}
        )`);
    },
    async run => {
        await run(`CREATE TABLE IF NOT EXISTS sessions (
            ${ID},
            user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
            token_hash TEXT NOT NULL UNIQUE,
            csrf_token TEXT NOT NULL,
            created_at ${TS},
            last_seen_at TEXT NOT NULL,
            expires_at TEXT NOT NULL,
            revoked_at TEXT,
            ip TEXT,
            user_agent TEXT
        )`);
        await run('CREATE INDEX IF NOT EXISTS idx_sessions_user ON sessions(user_id)');
        await run(`CREATE TABLE IF NOT EXISTS password_resets (
            ${ID},
            user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
            token_hash TEXT NOT NULL UNIQUE,
            expires_at TEXT NOT NULL,
            used_at TEXT,
            created_at ${TS}
        )`);
        await run('CREATE INDEX IF NOT EXISTS idx_password_resets_user ON password_resets(user_id)');
    },
    async run => {
        await run('ALTER TABLE users ADD COLUMN IF NOT EXISTS email_verified_at TEXT');
        await run(`CREATE TABLE IF NOT EXISTS email_verifications (
            ${ID},
            user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
            token_hash TEXT NOT NULL UNIQUE,
            expires_at TEXT NOT NULL,
            used_at TEXT,
            created_at ${TS}
        )`);
        await run('CREATE INDEX IF NOT EXISTS idx_email_verifications_user ON email_verifications(user_id)');
    },
    async run => {
        await run(`CREATE TABLE IF NOT EXISTS avatars (
            name TEXT PRIMARY KEY,
            user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
            mime TEXT NOT NULL,
            data BYTEA NOT NULL,
            created_at ${TS}
        )`);
        await run('CREATE INDEX IF NOT EXISTS idx_avatars_user ON avatars(user_id)');
    },
];

module.exports = { createPool, translate, prepareSchema, MIGRATIONS };
